30	/**
31	 * Maps KeyboardEvent.code to the modifier prefix used in combo shortcuts
32	 * (e.g., "Command+K"). These are the generic modifier names without left/right
33	 * distinction, used when building combo hotkey strings.
34	 */
35	function codeToComboModifier(code: string): string | undefined {
36		switch (code) {
37			case "MetaLeft":
38			case "MetaRight":
39				return "Command";
40			case "ShiftLeft":
41			case "ShiftRight":
42				return "Shift";
43			case "AltLeft":
44			case "AltRight":
45				return "Alt";
46			case "ControlLeft":
47			case "ControlRight":
48				return "Control";
49			default:
50				return undefined;
51		}
52	}
53	
54	/**
55	 * Consistent ordering for modifier keys when building shortcut strings.
56	 */
57	const MOD_ORDER = [
58		"MetaLeft",
59		"MetaRight",
60		"ControlLeft",
61		"ControlRight",
62		"AltLeft",
63		"AltRight",
64		"ShiftLeft",
65		"ShiftRight",
66	];
67	
68	const CODE_TO_HOTKEY_KEY: Record<string, string> = {
69		Backquote: "`",
70		Backslash: "\\",
71		BracketLeft: "[",
72		BracketRight: "]",
73		Comma: ",",
74		Equal: "=",
75		Minus: "-",
76		Period: ".",
77		Quote: "'",
78		Semicolon: ";",
79		Slash: "/",
80		Space: "Space",
81		Tab: "Tab",
82		Enter: "Enter",
83		Escape: "Escape",
84		Backspace: "Backspace",
85		Delete: "Delete",
86		CapsLock: "CapsLock",
87		ArrowDown: "ArrowDown",
88		ArrowLeft: "ArrowLeft",
89		ArrowRight: "ArrowRight",
90		ArrowUp: "ArrowUp",
91	};
92	
93	interface UseHotkeyRecorderOptions {
94		onHotkeyRecorded?: (hotkey: string) => Promise<void>;
95		validator?: (hotkey: string) => string | null;
96		recorderId?: string;
97	}
98	
99	function keyEventToHotkeyKey(e: KeyboardEvent): string {
100		if (/^Key[A-Z]$/.test(e.code)) return e.code.slice(3);
101		if (/^Digit[0-9]$/.test(e.code)) return e.code.slice(5);
102		if (/^Numpad/.test(e.code)) return e.code;
103		if (/^F[0-9]{1,2}$/.test(e.code)) return e.code;
104		return CODE_TO_HOTKEY_KEY[e.code] ?? (e.key.length === 1 ? e.key.toUpperCase() : e.key);
105	}
106	
107	export function useHotkeyRecorder(options: UseHotkeyRecorderOptions = {}) {
108		const recorderId = options.recorderId || Math.random().toString(36);
109		const [isRecording, setIsRecording] = createSignal(false);
110		const [pendingHotkey, setPendingHotkey] = createSignal("");
111		const [error, setError] = createSignal<string | null>(null);
112	
113		// Track all currently held modifier codes for combo shortcuts
114		let heldModifierCodes = new Set<string>();
115		let pendingSystemHotkey = "";
116		let isStartingWatcher = false;
117	
118		const resetTracking = () => {
119			heldModifierCodes = new Set<string>();
120			pendingSystemHotkey = "";
121		};
122	
123		const setRecorderActive = (active: boolean) => {
124			void Result.tryPromise(() => emit("hotkey-recorder-active", { active }));
125		};
126	
127		const saveRecordedHotkey = async (hotkey: string) => {
128			const validationError = options.validator?.(hotkey);
129			if (validationError) {
130				setError(validationError);
131				return false;
132			}
133			setError(null);
134			const saved = await Result.tryPromise(async () => {
135				await (options.onHotkeyRecorded?.(hotkey) ?? updateHotkey(hotkey));
136			});
137			if (Result.isError(saved)) {
138				return false;
139			}
140			return true;
141		};
142	
143		/**
144		 * Build a display string for currently held modifiers.
145		 */
146		const buildModifierDisplay = (codes: Set<string>): string => {
147			if (codes.size === 1) {
148				const first = codes.values().next();
149				if (first.done) return "";
150				return modifierCodeToDisplay(first.value) ?? first.value;
151			}
152			const parts: string[] = [];
153			for (const mc of MOD_ORDER) {
154				if (codes.has(mc)) {
155					const display = modifierCodeToDisplay(mc);
156					if (display) parts.push(display);
157				}
158			}
159			return parts.join(" + ");
160		};
161	
162		const handleKeyDown = (e: KeyboardEvent) => {
163			if (!isRecording()) return;
164	
165			e.preventDefault();
166			e.stopPropagation();
167	
168			const code = e.code;
169	
170			if (isModifierCode(code)) {
171				// A modifier key was pressed — show current modifier state
172				heldModifierCodes.add(code);
173				setPendingHotkey(buildModifierDisplay(heldModifierCodes));
174			} else {
175				// A non-modifier key was pressed — build a standard combo shortcut string
176				const modifiers: string[] = [];
177				const addedModifiers = new Set<string>();
178	
179				for (const mc of MOD_ORDER) {
180					if (heldModifierCodes.has(mc)) {
181						const modName = codeToComboModifier(mc);
182						if (modName && !addedModifiers.has(modName)) {
183							modifiers.push(modName);
184							addedModifiers.add(modName);
185						}
186					}
187				}
188	
189				const keyPart = keyEventToHotkeyKey(e);
190				const hotkeyString = [...modifiers, keyPart].join("+");
191				setPendingHotkey(hotkeyString);
192			}
193		};
194	
195		const handleKeyUp = async (e: KeyboardEvent) => {
196			if (!isRecording()) return;
197	
198			const code = e.code;
199	
200			if (isModifierCode(code)) {
201				const systemHotkey = modifierCodeToSystemHotkey(code);
202				if (systemHotkey && pendingSystemHotkey) {
203					heldModifierCodes.delete(code);
204					return;
205				}
206	
207				if (heldModifierCodes.size === 1 && heldModifierCodes.has(code) && systemHotkey) {
208					const success = await saveRecordedHotkey(systemHotkey);
209					if (success) {
210						setIsRecording(false);
211						setPendingHotkey("");
212						resetTracking();
213						setRecorderActive(false);
214					}
215					return;
216				}
217	
218				heldModifierCodes.delete(code);
219	
220				// When all modifiers are released without a combo, just reset display
221				if (heldModifierCodes.size === 0) {
222					setPendingHotkey("");
223				} else {
224					// Update display with remaining modifiers
225					setPendingHotkey(buildModifierDisplay(heldModifierCodes));
226				}
227			} else {
228				// A non-modifier key was released — check if we have a valid combo shortcut
229				const pending = pendingHotkey();
230				if (pending?.includes("+")) {
231					const success = await saveRecordedHotkey(pending);
232					if (success) {
233						setIsRecording(false);
234						setPendingHotkey("");
235						resetTracking();
236						setRecorderActive(false);
237					}
238				}
239			}
240		};
241	
242		const unlistenSystemPressedPromise = listen<SystemKeyPressedPayload>(
243			"system-key-pressed",
244			(event) => {
245				if (!isRecording()) return;
246	
247				pendingSystemHotkey = systemHotkeyFromKeys(event.payload.pressedKeys);
248				setPendingHotkey(hotkeyDisplayName(pendingSystemHotkey));
249			}
250		);
251	
252		const unlistenSystemReleasedPromise = listen("system-keys-released", () => {
253			if (!isRecording()) return;
254			if (!pendingSystemHotkey) return;
255	
256			const hotkey = pendingSystemHotkey;
257			void Result.tryPromise(() =>
258				saveRecordedHotkey(hotkey).then((success) => {
259					if (success) {
260						setIsRecording(false);
261						setPendingHotkey("");
262						resetTracking();
263						setRecorderActive(false);
264					}
265				})
266			);
267		});
268	
269		createEffect(() => {
270			if (isRecording()) {
271				resetTracking();
272				window.addEventListener("keydown", handleKeyDown);
273				window.addEventListener("keyup", handleKeyUp);
274			} else {
275				window.removeEventListener("keydown", handleKeyDown);
276				window.removeEventListener("keyup", handleKeyUp);
277			}
278		});
279	
280		onCleanup(() => {
281			window.removeEventListener("keydown", handleKeyDown);
282			window.removeEventListener("keyup", handleKeyUp);
283			if (activeRecordingId === recorderId) {
284				activeRecordingId = null;
285			}
286			setRecorderActive(false);
287			void Result.tryPromise(() => unlistenSystemPressedPromise.then((unlisten) => unlisten()));
288			void Result.tryPromise(() => unlistenSystemReleasedPromise.then((unlisten) => unlisten()));
289		});
290	
291		const startRecording = async () => {
292			if (activeRecordingId !== null && activeRecordingId !== recorderId) {
293				setError("Another hotkey is being recorded. Please finish or cancel it first.");
294				return;
295			}
296			if (isStartingWatcher) return;
297			isStartingWatcher = true;
298			const watcherStarted = await startSystemKeyWatcher();
299			isStartingWatcher = false;
300			if (Result.isError(watcherStarted)) {
301				setError(watcherStarted.error.message);
302				return;
303			}
304			activeRecordingId = recorderId;
305			setIsRecording(true);
306			setPendingHotkey("");
307			setError(null);
308			resetTracking();
309			setRecorderActive(true);
310		};
311	
312		const stopRecording = () => {
313			if (activeRecordingId === recorderId) {
314				activeRecordingId = null;
315			}
316			setIsRecording(false);
317			setPendingHotkey("");
318			setError(null);
319			resetTracking();
320			setRecorderActive(false);
321		};
322	
323		return {
324			isRecording,
325			pendingHotkey,
326			error,
327			startRecording,
328			stopRecording,
329			toggleRecording: () => {
330				if (isRecording()) {
331					stopRecording();
332				} else {
333					void startRecording();
334				}
335			},
336		};
337	}
